<?php
namespace App\Services;use App\Models\{Committee,CommitteeOperationalAlert};
class CommitteeAlertService{public function __construct(private CommitteeRegulationService $rules){}public function check():int{$created=0;foreach(Committee::where('status','active')->with('latestFinalFormation')->get() as $committee){if($this->rules->requiresMonthlyMeeting($committee->type)&&!$committee->scheduleItems()->where('activity_type','ordinary_meeting')->whereYear('scheduled_date',today()->year)->whereMonth('scheduled_date',today()->month)->whereNotIn('status',['cancelled'])->exists())$created+=$this->alert($committee,'missing_monthly_meeting',null,today(),'warning','No existe reunión ordinaria programada para el mes actual.');foreach($committee->scheduleItems()->whereDate('scheduled_date','<',today())->whereNotIn('status',['completed','cancelled'])->get() as $item)$created+=$this->alert($committee,'overdue_activity',$item,today(),'critical','Actividad del cronograma vencida: '.$item->title);foreach($committee->commitments()->whereDate('due_date','<',today())->whereNotIn('status',['completed','cancelled'])->get() as $commitment)$created+=$this->alert($committee,'overdue_commitment',$commitment,today(),'critical','Compromiso vencido: '.$commitment->description);}return$created;}private function alert(Committee $committee,string $type,$reference,$date,string $severity,string $message):int{$alert=CommitteeOperationalAlert::firstOrCreate(['committee_id'=>$committee->id,'alert_type'=>$type,'reference_type'=>$reference?->getMorphClass(),'reference_id'=>$reference?->id,'alert_date'=>$date],['severity'=>$severity,'message'=>$message]);return$alert->wasRecentlyCreated?1:0;}}
